const weakMap = new WeakMap()
const obj1 = { name: "user1" }
const obj2 = { name: "user2" }
weakMap.set(obj1, "data1")
weakMap.set(obj2, "data2")
return {
  data1: weakMap.get(obj1),
  data2: weakMap.get(obj2),
  hasObj1: weakMap.has(obj1)
}
